1	//! One component's props from the checker: the export's call signature, its first parameter's type, that type's
2	//! properties.
3	
4	use std::sync::Arc;
5	
6	use caliper_docgen_core::types::ComponentExport;
7	use caliper_docgen_core::types::PropParent;
8	use caliper_docgen_core::types::semantic::{PropInterner, SemanticProp, unconverted_type};
9	
10	use crate::Target;
11	use crate::convert::{Converter, PropKey, declared_in, without_undefined};
12	use crate::declared::Asked;
13	use crate::instantiate::{self, Instantiation};
14	use crate::rpc::{CallError, Rpc, SignatureKind, SymbolInfo, TypeInfo, flag};
15	
16	pub(crate) enum Answer {
17	    Props(Props),
18	    /// The component keeps its structural result, for this reason.
19	    Fallback(String),
20	    /// A generic component, whose props are read from an instantiation of it ([`crate::instantiate`]).
21	    Instantiate(Instantiation),
22	}
23	
24	/// What the checker says about one component's props type.
25	pub(crate) struct Props {
26	    pub(crate) props: Vec<Arc<SemanticProp>>,
27	    /// See [`caliper_docgen_core::types::semantic::SemanticComponent::composes`].
28	    pub(crate) composes: Option<Vec<String>>,
29	    /// See [`caliper_docgen_core::types::semantic::SemanticComponent::whole`].
30	    pub(crate) whole: Vec<PropParent>,
31	}
32	
33	/// What `@types/react` declares (`key`, `ref`, `children` on `PropsWithChildren`, HTML attributes) and the project does
34	/// not. Reported with the flag set when the request asks for the name; what to do with them is the session's policy, not
35	/// ours. A property a project file also declares (`ComponentProps<'div'> & { className: 'mine' }`) is the component's
36	/// own and never React's. One a dependency declares again over React's (a library's `className`, its DOM handlers)
37	/// stays React's: the element layer stands for it.
38	fn is_react_declared(property: &SymbolInfo) -> bool {
39	    use caliper_docgen_core::origin::{Origin, declaration_origin};
40	    let files = || property.declarations.iter().map(|declaration| declared_in(declaration));
41	    files().any(|file| declaration_origin(file) == Origin::React) && files().all(|file| file.contains("/node_modules/"))
42	}
43	
44	fn fallback(reason: &str) -> Result<Answer, CallError> {
45	    Ok(Answer::Fallback(reason.to_string()))
46	}
47	
48	/// A module as the checker reads it: its own symbol, whose declaration names its file in the checker's spelling, and
49	/// its exports.
50	pub(crate) struct Module {
51	    pub(crate) symbol: SymbolInfo,
52	    pub(crate) exports: Vec<SymbolInfo>,
53	}
54	
55	impl Module {
56	    /// Whether one of `symbol`'s declarations is in this module's file.
57	    fn declares(&self, symbol: &SymbolInfo) -> bool {
58	        let files: Vec<&str> = self.symbol.declarations.iter().map(|declaration| declared_in(declaration)).collect();
59	        symbol.declarations.iter().any(|declaration| files.contains(&declared_in(declaration)))
60	    }
61	}
62	
63	/// The symbol `export` names in `module`: the export of exactly that name, through an alias to what it aliases, then
64	/// each property an attached sub-component is reached through. `Err` says why there is none, or why it is not the
65	/// component the extractor found: one declared in another file.
66	async fn exported_symbol(
67	    rpc: &Rpc,
68	    module: &Module,
69	    export: &ComponentExport,
70	) -> Result<Result<SymbolInfo, String>, CallError> {
71	    let Some(symbol) = module.exports.iter().find(|symbol| symbol.name == export.name) else {
72	        return Ok(Err(format!("the checker finds no export `{}` in its module", export.name)));
73	    };
74	    let mut symbol = if symbol.flags & flag::SYMBOL_ALIAS != 0 {
75	        rpc.aliased_symbol(&symbol.reference).await?
76	    } else {
77	        symbol.clone()
78	    };
79	    for member in &export.members {
80	        let parent = rpc.type_of_symbol(&symbol.reference).await?;
81	        let Some(property) = rpc.properties(parent.id).await?.into_iter().find(|property| property.name == *member)
82	        else {
83	            return Ok(Err(format!("the checker finds no property `{member}` on the export `{}`", export.name)));
84	        };
85	        symbol = property;
86	    }
87	    if !module.declares(&symbol) {
88	        return Ok(Err(format!("the export `{export}` is declared in another file")));
89	    }
90	    Ok(Ok(symbol))
91	}
92	
93	/// The component's symbol: the first export the extractor recorded for it that the checker finds. Never another
94	/// export, such as the module's `default` when `default` is not one of them.
95	async fn component_symbol(
96	    rpc: &Rpc,
97	    module: &Module,
98	    target: &Target,
99	) -> Result<Result<(SymbolInfo, ComponentExport), String>, CallError> {
100	    let mut reasons = Vec::new();
101	    for export in &target.exports {
102	        match exported_symbol(rpc, module, export).await? {
103	            Ok(symbol) => return Ok(Ok((symbol, export.clone()))),
104	            Err(reason) => reasons.push(reason),
105	        }
106	    }
107	    Ok(Err(if reasons.is_empty() { "not exported by its module".to_string() } else { reasons.join("; ") }))
108	}
109	
110	pub(crate) async fn props_of(
111	    rpc: &Rpc,
112	    converter: &Converter,
113	    interner: &PropInterner,
114	    module: &Module,
115	    target: &Target,
116	) -> Result<Answer, CallError> {
117	    let (symbol, export) = match component_symbol(rpc, module, target).await? {
118	        Ok(found) => found,
119	        Err(reason) => return Ok(Answer::Fallback(reason)),
120	    };
121	
122	    let component = rpc.type_of_symbol(&symbol.reference).await?;
123	    let signatures = rpc.signatures(component.id, SignatureKind::Call).await?;
124	    let [signature] = signatures.as_slice() else {
125	        return fallback(if signatures.is_empty() {
126	            "no call signature (class or non-function component)"
127	        } else {
128	            "overloaded call signatures"
129	        });
130	    };
131	    let parameters = rpc.parameters(signature.id).await?;
132	    let Some(first) = parameters.first() else { return fallback("takes no props parameter") };
133	    if let Some(arguments) = instantiate::default_arguments(rpc, signature).await? {
134	        if !export.members.is_empty() {
135	            return fallback("a generic sub-component reached through its parent's property is not instantiated");
136	        }
137	        return Ok(Answer::Instantiate(Instantiation { export: export.name, arguments }));
138	    }
139	
140	    let props_type = rpc.type_of_symbol(&first.reference).await?;
141	    Ok(props_of_type(rpc, converter, interner, &props_type, target).await?.map_or_else(Answer::Fallback, Answer::Props))
142	}
143	
144	/// The props a component's props type holds, or why the component keeps its structural result.
145	pub(crate) async fn props_of_type(
146	    rpc: &Rpc,
147	    converter: &Converter,
