15	/// RDT's type-name convention for literal unions: `{"name": "enum", "value": [...]}`
16	/// instead of inlining the literal text into `type.name` as a plain string. Lets
17	/// prop-table renderers that pattern-match `type.name === "enum"` (a common
18	/// Storybook addon integration point) show a `<select>` control for the most
19	/// common, most curated props in any design system (variant, size, color…).
20	/// A single string or number literal is a one-option enum, as Storybook's own docgen has it. An enum member's option is
21	/// its value (`"small"` for `Size.Small`, `PropType::option_text`), which is what the control passes.
22	///
23	/// Storybook unquotes each option's source text into a string or a number, so `true` in an enum would reach the control
24	/// as the string "true". A union with a boolean member therefore stays a type name, which Storybook's converter splits
25	/// at the `|` and parses as JSON into the options `["a", 1, true]`, unless a member's text would not survive that (a
26	/// string holding `|`, `"` or `\`); it is then an enum, so that no option is lost.
27	pub fn type_json(prop_type: &PropType) -> serde_json::Value {
28	    if prop_type.is_literal_union() {
29	        let values: Vec<serde_json::Value> = match prop_type {
30	            PropType::Union(members) => members.iter().map(|m| serde_json::json!({"value": m.option_text()})).collect(),
31	            PropType::LiteralUnion { members, .. } => {
32	                members.iter().map(|m| serde_json::json!({"value": format!("\"{m}\"")})).collect()
33	            }
34	            single => vec![serde_json::json!({"value": single.option_text()})],
35	        };
36	        return serde_json::json!({ "name": "enum", "raw": prop_type.raw_string(), "value": values });
37	    }
38	    serde_json::json!({ "name": prop_type.raw_string() })
39	}
40	
41	/// RDT's default `skipChildrenPropWithoutDoc`: an undocumented `children` says nothing a
42	/// prop table can show, so RDT never emits it. Canonical output keeps it.
43	pub fn omits(prop: &ParsedProp) -> bool {
44	    prop.name == "children" && prop.description.is_empty()
45	}
46	
47	/// One prop as RDT documents it.
48	fn prop_json(prop: &ParsedProp) -> serde_json::Value {
49	    serde_json::json!({
50	        "name": prop.name,
51	        "type": type_json(&prop.prop_type),
52	        "required": prop.required,
53	        "defaultValue": prop.default_value.as_ref().map(|d| serde_json::json!({"value": d.value, "computed": d.computed})),
54	        "description": prop.description,
55	        "parent": prop.parent.as_ref().map(|p| serde_json::json!({"name": p.name, "fileName": p.file_name})),
56	    })
57	}
58	
59	/// The props a props table lists: the component's own and inherited ones, then the curated attributes inherited from an
60	/// HTML element, which `curated` mode keeps apart so the canonical output can collapse them. A prop named in both is
61	/// listed once, as the component declares it. A prop tagged `@ignore` is left out, as Storybook's own docgen leaves it
62	/// out; the canonical output keeps it.
63	fn listed_props<'a>(
64	    entry: &'a ComponentEntry,
65	    keep: impl Fn(&ParsedProp) -> bool + 'a,
66	) -> impl Iterator<Item = (&'a String, &'a Arc<ParsedProp>)> {
67	    entry
68	        .props
69	        .iter()
70	        .chain(entry.notable_inherited.iter().filter(|(name, _)| !entry.props.contains_key(*name)))
71	        .filter(move |(_, prop)| keep(prop) && !prop.tags.contains_key("ignore"))
72	}
73	
74	/// One component as RDT documents it, except that an undocumented `children` stays: this is the `__docgenInfo`
75	/// Storybook's React renderer converts, and its own docgen lists `children`. `methods` is always `[]` — this tool
76	/// doesn't extract class methods, and Storybook only reads it for class components.
77	pub fn docgen_info(entry: &ComponentEntry) -> serde_json::Value {
78	    let props: serde_json::Map<String, serde_json::Value> =
79	        listed_props(entry, |_| true).map(|(k, prop)| (k.clone(), prop_json(prop))).collect();
80	    serde_json::json!({
81	        "displayName": entry.display_name,
82	        "props": serde_json::Value::Object(props),
83	        "description": entry.description,
84	        "methods": [],
85	        "tags": entry.tags,
86	        "composes": entry.composes,
87	    })
88	}
89	
90	/// Indentation a prop's lines take in the pretty-printed document: it sits in a component, in that component's
91	/// `props`, in the document: three objects deep, two spaces each.
92	const PROP_INDENT: &str = "      ";
93	
94	/// A prop as the document holds it, rendered once. Pretty printing a prop alone indents by its own depth only, and a
95	/// JSON string holds no raw newline, so every newline is a line break of the layout and the document's nesting is all
96	/// that is left to add.
97	fn render_prop(prop: &ParsedProp) -> serde_json::Result<Box<RawValue>> {
98	    let pretty = serde_json::to_string_pretty(&prop_json(prop))?;
99	    let mut indented = String::with_capacity(pretty.len() + PROP_INDENT.len() * 8);
100	    for (i, line) in pretty.split('\n').enumerate() {
101	        if i > 0 {
102	            indented.push('\n');
103	            indented.push_str(PROP_INDENT);
104	        }
105	        indented.push_str(line);
106	    }
107	    RawValue::from_string(indented)
108	}
109	
110	/// Rendered props by the address of the allocation that holds them.
111	type Rendered = FxHashMap<usize, Box<RawValue>>;
112	
113	fn address(prop: &Arc<ParsedProp>) -> usize {
114	    Arc::as_ptr(prop) as usize
115	}
116	
117	/// The listed props of one component, each already rendered.
118	struct Props<'a> {
119	    entry: &'a ComponentEntry,
120	    rendered: &'a Rendered,
121	}
122	
123	impl Serialize for Props<'_> {
124	    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
125	        let mut map = serializer.serialize_map(None)?;
126	        for (name, prop) in listed_props(self.entry, |prop| !omits(prop)) {
127	            map.serialize_entry(name, &self.rendered[&address(prop)])?;
128	        }
129	        map.end()
130	    }
131	}
132	
133	struct Doc<'a> {
134	    entry: &'a ComponentEntry,
135	    rendered: &'a Rendered,
136	}
137	
138	impl Serialize for Doc<'_> {
139	    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
140	        let entry = self.entry;
141	        let mut doc = serializer.serialize_struct("ComponentDoc", 7)?;
142	        doc.serialize_field("displayName", &entry.display_name)?;
143	        doc.serialize_field("props", &Props { entry, rendered: self.rendered })?;
144	        doc.serialize_field("description", &entry.description)?;
145	        doc.serialize_field("methods", &[(); 0])?;
146	        doc.serialize_field("tags", &entry.tags)?;
147	        doc.serialize_field("composes", &entry.composes)?;
148	        doc.serialize_field("filePath", &entry.file_path)?;
149	        doc.end()
150	    }
151	}
152	
153	struct Docs<'a> {
154	    components: Vec<(&'a String, &'a ComponentEntry)>,
155	    rendered: Rendered,
156	}
157	
158	impl Serialize for Docs<'_> {
159	    fn serialize<S: Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
160	        let mut map = serializer.serialize_map(Some(self.components.len()))?;
161	        for (name, entry) in &self.components {
162	            map.serialize_entry(name, &Doc { entry, rendered: &self.rendered })?;
163	        }
164	        map.end()
165	    }
166	}
167	
168	/// Render the props of the components `output` documents, once each.
169	fn documents(output: &ExtractionOutput, include_unexported: bool) -> serde_json::Result<Docs<'_>> {
170	    let components: Vec<_> =
171	        output.components.iter().filter(|(_, entry)| include_unexported || entry.exported).collect();
172	    let mut distinct: FxHashMap<usize, &Arc<ParsedProp>> = FxHashMap::default();
173	    for (_, entry) in &components {
174	        for (_, prop) in listed_props(entry, |prop| !omits(prop)) {
175	            distinct.entry(address(prop)).or_insert(prop);
176	        }
177	    }
178	    let rendered = distinct
179	        .into_par_iter()
180	        .map(|(address, prop)| Ok((address, render_prop(prop)?)))
181	        .collect::<serde_json::Result<_>>()?;
182	    Ok(Docs { components, rendered })
183	}
184	
185	/// The components of `output` as RDT documents them, keyed as in the output, pretty-printed to `writer` with no
186	/// trailing newline. Like RDT, only exported components unless `include_unexported`, each with RDT's `filePath`, which
187	/// `__docgenInfo` doesn't carry.
188	///
189	/// Components that inherit one interface share its props' allocations, so a project's few thousand distinct props occur
190	/// half a million times: each is rendered once and its bytes written wherever it occurs, and the document is never held
191	/// whole.
192	pub fn write(output: &ExtractionOutput, include_unexported: bool, writer: impl Write) -> serde_json::Result<()> {
193	    serde_json::to_writer_pretty(writer, &documents(output, include_unexported)?)
194	}
195	
196	/// [`write()`] to a string.
197	pub fn serialize(output: &ExtractionOutput, include_unexported: bool) -> serde_json::Result<String> {
198	    serde_json::to_string_pretty(&documents(output, include_unexported)?)
199	}
